import 'package:flutter/material.dart';import 'package:sizer/sizer.dart';class CustomSwitch extends StatelessWidget {  final String? text;  final bool value;  final ValueChanged<bool>? onChanged;  const CustomSwitch(      {super.key, this.text, required this.value, required this.onChanged});  @override  Widget build(BuildContext context) {    return Row(      mainAxisAlignment: MainAxisAlignment.spaceBetween,      children: [        if (text != null)          Text(            text!,            style: TextStyle(              fontSize: 12.5.sp,              fontWeight: FontWeight.normal,            ),          ),        SizedBox(          height: 3.5.h,          child: Switch(            materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,            value: value,            onChanged: onChanged,          ),        ),      ],    );  }}